using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Agents.AI;
using OpenAI;

// --- Configuration -----------------------------------------------------------

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

var topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptForTopic();

Console.WriteLine($"\n🔍  Researching: {topic}\n");

// --- Chat client (MEAI abstraction over OpenAI) ------------------------------

IChatClient chatClient = new ChatClientBuilder(
        new OpenAIClient(apiKey).GetChatClient(modelId).AsIChatClient())
    .UseFunctionInvocation()
    .Build();

// --- Tools -------------------------------------------------------------------

var notepad = new Notepad();
var tools = new AITool[]
{
    AIFunctionFactory.Create(SearchWeb),
    AIFunctionFactory.Create(notepad.SaveNote),
    AIFunctionFactory.Create(notepad.ReadNotes),
};

// --- Agent -------------------------------------------------------------------

var agent = new ChatClientAgent(
    chatClient,
    name: "ResearchAgent",
    description: "An AI research assistant that searches the web and takes notes.",
    instructions: """
        You are a research assistant. When given a topic:
        1. Search the web for relevant information using multiple queries.
        2. Save important findings as notes.
        3. After gathering enough information, read your notes and produce a
           well-structured summary with key points and sources.
        Be thorough — perform at least 2-3 different searches before summarizing.
        """,
    tools: tools);

var runOptions = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
});

// --- Run ---------------------------------------------------------------------

var session = await agent.CreateSessionAsync();
var response = await agent.RunAsync(
    $"Research the following topic and provide a detailed summary: {topic}",
    session,
    runOptions);

Console.WriteLine("\n══════════════════════════════════════════════════════════════");
Console.WriteLine("  📝  RESEARCH SUMMARY");
Console.WriteLine("══════════════════════════════════════════════════════════════\n");
Console.WriteLine(response.Text);
Console.WriteLine();

// --- Tool implementations ----------------------------------------------------

[Description("Searches the web for the given query and returns a list of result snippets.")]
static string SearchWeb(
    [Description("The search query to look up on the web.")] string query)
{
    Console.WriteLine($"  🌐  Searching: \"{query}\"");

    // Simulated web search results — swap with a real search API (e.g. Bing) in production.
    var results = query.ToLowerInvariant() switch
    {
        var q when q.Contains("artificial intelligence") || q.Contains(" ai ") || q.Contains("ai ") =>
            """
            1. "Artificial Intelligence: A Modern Approach" — AI encompasses machine learning,
               natural language processing, robotics, and computer vision. (Source: Stanford CS221)
            2. Recent breakthroughs include large language models (LLMs) like GPT-4 and Gemini
               that demonstrate emergent reasoning capabilities. (Source: arxiv.org, 2024)
            3. Global AI market projected to reach $1.8 trillion by 2030, growing at 37% CAGR.
               (Source: Grand View Research, 2024)
            """,
        var q when q.Contains("climate") || q.Contains("environment") || q.Contains("warming") =>
            """
            1. Global temperatures have risen ~1.1°C above pre-industrial levels; the Paris
               Agreement targets limiting warming to 1.5°C. (Source: IPCC AR6, 2023)
            2. Renewable energy capacity additions hit a record 507 GW in 2023, led by solar.
               (Source: IRENA, 2024)
            3. Ocean acidification has increased 30% since the industrial revolution, threatening
               marine ecosystems. (Source: NOAA, 2024)
            """,
        var q when q.Contains("quantum") =>
            """
            1. Quantum computing uses qubits that leverage superposition and entanglement to solve
               certain problems exponentially faster. (Source: IBM Research, 2024)
            2. Google's Willow chip achieved quantum error correction below threshold, a key
               milestone toward practical quantum computers. (Source: Nature, 2024)
            3. Applications span cryptography, drug discovery, optimization, and materials science.
               (Source: McKinsey Quantum Technology Monitor, 2024)
            """,
        _ =>
            $"""
            1. "{query}" is an active area of research with growing academic and industry interest.
               (Source: Google Scholar)
            2. Recent publications highlight new developments and emerging trends in this field.
               (Source: arxiv.org, 2024)
            3. Market analysts project significant growth and investment in this domain over the
               next decade. (Source: Industry Reports, 2024)
            """
    };

    return results;
}

static string PromptForTopic()
{
    Console.Write("Enter a research topic: ");
    var input = Console.ReadLine()?.Trim();
    return string.IsNullOrEmpty(input)
        ? "Recent advances in artificial intelligence"
        : input;
}

// --- Notepad tool class ------------------------------------------------------

sealed class Notepad
{
    private readonly List<string> _notes = [];

    [Description("Saves an important finding or note for later reference.")]
    public string SaveNote(
        [Description("The note content to save.")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  📌  Note saved ({_notes.Count} total)");
        return $"Note saved. You now have {_notes.Count} note(s).";
    }

    [Description("Reads all previously saved notes.")]
    public string ReadNotes()
    {
        if (_notes.Count == 0)
            return "No notes have been saved yet.";

        Console.WriteLine($"  📖  Reading {_notes.Count} note(s)");
        return string.Join("\n\n---\n\n",
            _notes.Select((n, i) => $"Note {i + 1}:\n{n}"));
    }
}

